import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC01%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E5%8C%96%E5%8F%91%E5%B1%95/1.4%20%E6%95%B0%E5%AD%97%E4%B8%AD%E5%9B%BD.html","title":"1.4 数字中国","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第01章 信息化发展/1.4 数字中国.md"}`),a={name:`1.4 数字中国.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_1-4-数字中国" tabindex="-1"><a class="header-anchor" href="#_1-4-数字中国"><span>1.4 数字中国</span></a></h1><h2 id="数字经济" tabindex="-1"><a class="header-anchor" href="#数字经济"><span>数字经济</span></a></h2><h3 id="一、内容分类" tabindex="-1"><a class="header-anchor" href="#一、内容分类"><span>一、内容分类</span></a></h3><h4 id="_1-具体分类" tabindex="-1"><a class="header-anchor" href="#_1-具体分类"><span>1. 具体分类</span></a></h4><ul><li><strong>数字产业化</strong><ol><li>数字产品制造业</li><li>数字产品服务业</li><li>数字技术应用业</li><li>数字要素驱动业</li></ol></li><li><strong>产业数字化</strong>：数字化效率提升业</li></ul><h4 id="_2-整体构成分类" tabindex="-1"><a class="header-anchor" href="#_2-整体构成分类"><span>2. 整体构成分类</span></a></h4><p>数字产业化、产业数字化、数字化治理、数据价值化</p><h3 id="二、数字产业化" tabindex="-1"><a class="header-anchor" href="#二、数字产业化"><span>二、数字产业化</span></a></h3><ol><li>数字产业化发展重点包括：<strong>云计算、大数据、工业互联网、区块链、人工智能、虚拟现实和增强现实</strong></li></ol><h3 id="三、产业数字化" tabindex="-1"><a class="header-anchor" href="#三、产业数字化"><span>三、产业数字化</span></a></h3><p>核心纲领：<strong>以数据为关键要素，以价值释放为核心，以数据赋能为主线</strong></p><p>记忆：扼要辅助加解</p><h4 id="产业数字化的典型特征" tabindex="-1"><a class="header-anchor" href="#产业数字化的典型特征"><span>产业数字化的典型特征</span></a></h4><ol><li>以数字科技变革生产工具</li><li>以数据资源为关键生产要素</li><li>以数字内容重构产品结构</li><li>以信息网络为市场配置纽带</li><li>以服务平台为产业生态载体</li><li>以数字善治为发展机制条件</li></ol><h2 id="数字化治理" tabindex="-1"><a class="header-anchor" href="#数字化治理"><span>数字化治理</span></a></h2><h3 id="_1-定义" tabindex="-1"><a class="header-anchor" href="#_1-定义"><span>1. 定义</span></a></h3><p>依托互联网、大数据、人工智能等，创新社会治理方法与手段，优化社会治理模式，推进社会治理的科学化、精细化、高效化，助力社会治理现代化</p><h3 id="_2-核心特征" tabindex="-1"><a class="header-anchor" href="#_2-核心特征"><span>2. 核心特征</span></a></h3><p>全社会的数据互通、数字化全面协同与跨部门的流程再造，形成<strong>用数据说话、用数据决策、用数据管理、用数据创新</strong>的治理机制</p><h3 id="_3-内容" tabindex="-1"><a class="header-anchor" href="#_3-内容"><span>3. 内容</span></a></h3><ol><li><strong>对数据的治理</strong></li></ol><p>成为制定数字经济规则的重要内容，数据要素的所有权、使用权、监管权，以及信息保护和数据安全等都需要全新治理体系</p><ol start="2"><li><strong>运用数据进行治理</strong></li></ol><p>运用数字与智能技术优化治理技术体系，进而提升治理能力</p><ol start="3"><li><strong>对数字融合空间进行治理</strong></li></ol><p>治理场域也拓展到数字空间</p><h2 id="数据价值化" tabindex="-1"><a class="header-anchor" href="#数据价值化"><span>数据价值化</span></a></h2><h3 id="_1-覆盖范围" tabindex="-1"><a class="header-anchor" href="#_1-覆盖范围"><span>1. 覆盖范围</span></a></h3><ol><li>数据价值化包括但不限于数据采集、数据标准、数据确权、数据标注、数据定价、数据交易、数据流转、数据保护</li><li>数据价值化是以<strong>数据资源化</strong>为起点</li></ol><h3 id="_2-数据价值化三化框架" tabindex="-1"><a class="header-anchor" href="#_2-数据价值化三化框架"><span>2. 数据价值化三化框架</span></a></h3><ol><li><strong>数据资源化</strong></li></ol><p>使无序、混乱的原始数据成为有序、有使用价值的数据资源</p><p>数据资源化是激发数据价值的基础，其本质是提升数据质量，形成数据使用价值的过程</p><ol start="2"><li><strong>数据资产化</strong></li></ol><p>数据通过流通交易给使用者或者所有者带来的经济利益的过程。是实现数据价值的核心，其本质是形成数据交换价值，初步实现数据价值</p><ol start="3"><li><strong>数据资本化</strong></li></ol><p>主要包括两种方式：<strong>数据信贷融资、数据证券化</strong></p><p>是拓展数据价值的途径，其本质是实现数据要素社会化配置</p>`,38)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};